1	import { app } from 'electron'
2	import { EventEmitter } from 'node:events'
3	import { existsSync, readFileSync, writeFileSync, mkdirSync, renameSync } from 'node:fs'
4	import { writeFile, mkdir, rename } from 'node:fs/promises'
5	import path from 'node:path'
6	
7	// 에이전트 실행 이력 — 에이전트가 수행한 작업(지시·단계·결과)을 저장해 나중에 되짚어볼 수 있게 한다.
8	// 메인에서 기록하므로 사이드바를 닫아도 남는다. userData/ai-agent-runs.json.
9	
10	export type AgentRunStatus = 'running' | 'done' | 'error' | 'cancelled'
11	export interface AgentRunStep { icon: string; text: string; tone?: 'ok' | 'warn' | 'muted' }
12	export interface AgentRun {
13	  id: string
14	  task: string
15	  startedAt: number
16	  endedAt?: number
17	  status: AgentRunStatus
18	  steps: AgentRunStep[]
19	  result?: string
20	  // 토큰 합계(CLI 세션 경로가 스텝마다 usage 를 방출할 때만 채워진다) — 효율 벤치·사용자 확인용.
21	  usage?: { input: number; cacheRead: number; cacheCreate: number; output: number; llmCalls: number }
22	}
23	export interface AgentRunSummary {
24	  id: string
25	  task: string
26	  startedAt: number
27	  endedAt?: number
28	  status: AgentRunStatus
29	  stepCount: number
30	}
31	
32	export const agentRunEvents = new EventEmitter()
33	
34	const MAX_RUNS = 50
35	const MAX_STEPS_PER_RUN = 120
36	let cache: AgentRun[] | null = null
37	let writeTimer: NodeJS.Timeout | null = null
38	let dirty = false
39	let quitHooked = false
40	
41	function filePath(): string {
42	  return path.join(app.getPath('userData'), 'ai-agent-runs.json')
43	}
44	
45	function isValid(r: unknown): r is AgentRun {
46	  if (!r || typeof r !== 'object') return false
47	  const o = r as Record<string, unknown>
48	  return typeof o.id === 'string' && typeof o.task === 'string' && Array.isArray(o.steps)
49	}
50	
51	export function initAgentRuns(): void {
52	  if (!quitHooked) { quitHooked = true; try { app.on('before-quit', flushAgentRuns) } catch { /* ignore */ } }
53	  if (cache !== null) return
54	  try {
55	    if (existsSync(filePath())) {
56	      const raw = JSON.parse(readFileSync(filePath(), 'utf-8')) as { runs?: unknown }
57	      cache = Array.isArray(raw?.runs) ? raw.runs.filter(isValid) : []
58	      // 재시작 시 'running' 으로 남은 것은 중단된 것으로 정리
59	      for (const r of cache) { if (r.status === 'running') { r.status = 'cancelled'; r.endedAt = r.endedAt ?? r.startedAt } }
60	    } else {
61	      cache = []
62	    }
63	  } catch (err) {
64	    console.warn('[ai] agent runs load failed', err)
65	    cache = []
66	  }
67	}
68	
69	function all(): AgentRun[] {
70	  if (cache === null) initAgentRuns()
71	  return cache ?? []
72	}
73	
74	function schedulePersist(): void {
75	  dirty = true
76	  if (writeTimer) clearTimeout(writeTimer)
77	  writeTimer = setTimeout(() => { void persist() }, 400)
78	}
79	
80	async function persist(): Promise<void> {
81	  try {
82	    await mkdir(path.dirname(filePath()), { recursive: true })
83	    const tmp = filePath() + '.tmp'
84	    await writeFile(tmp, JSON.stringify({ version: 1, runs: all() }), 'utf-8')
85	    await rename(tmp, filePath())
86	    dirty = false
87	  } catch (err) {
88	    console.warn('[ai] agent runs persist failed', err)
89	  }
90	}
91	
92	export function flushAgentRuns(): void {
93	  if (writeTimer) { clearTimeout(writeTimer); writeTimer = null }
94	  if (!dirty) return
95	  try {
96	    mkdirSync(path.dirname(filePath()), { recursive: true })
97	    const tmp = filePath() + '.tmp' // 원자적 쓰기 — 종료 중 크래시로 파일이 잘리지 않도록
98	    writeFileSync(tmp, JSON.stringify({ version: 1, runs: all() }), 'utf-8')
99	    renameSync(tmp, filePath())
100	    dirty = false
101	  } catch (err) {
102	    console.warn('[ai] agent runs flush failed', err)
103	  }
104	}
105	
106	function summaryOf(r: AgentRun): AgentRunSummary {
107	  return { id: r.id, task: r.task, startedAt: r.startedAt, endedAt: r.endedAt, status: r.status, stepCount: r.steps.length }
108	}
109	
110	function emitChanged(): void {
111	  agentRunEvents.emit('changed', listAgentRuns())
112	}
113	
114	export function listAgentRuns(): AgentRunSummary[] {
115	  return all().slice().sort((a, b) => b.startedAt - a.startedAt).map(summaryOf)
116	}
117	
118	export function getAgentRun(id: string): AgentRun | null {
119	  return all().find((r) => r.id === id) ?? null
120	}
121	
122	// 실행 이력은 디스크에 평문으로 남는다. 비밀번호·카드번호·토큰처럼 남으면 안 되는 값은 가린다.
123	const CARD_LIKE = /\b(?:\d[ -]?){13,19}\b/g
124	const TOKEN_LIKE = /\b(?:sk|pk|ghp|xox[baprs])[-_][A-Za-z0-9_-]{12,}\b|\bBearer\s+[A-Za-z0-9._-]{12,}/gi
125	// 공백 없이 이어진 12자 이상 + 숫자·기호가 섞인 문자열 = 비밀번호일 가능성이 높다(URL·이메일은 제외).
126	const PASSWORD_LIKE = /(?<![\w./:@-])(?!https?:\/\/|www\.)(?=[^\s]{12,})(?=[^\s]*\d)(?=[^\s]*[^\w\s])(?![^\s]*@)[^\s]{12,}(?![\w./-])/g
127	
128	function maskSecrets(text: string): string {
129	  return String(text ?? '')
130	    .replace(TOKEN_LIKE, '[가림: 토큰]')
131	    .replace(CARD_LIKE, '[가림: 번호]')
132	    .replace(PASSWORD_LIKE, '[가림]')
133	}
134	
135	// 에이전트 이벤트를 사람이 읽는 단계로 변환(AiTab 라이브 트레이스와 동일 매핑).
136	type EventLike = { type: string; [k: string]: unknown }
137	function deriveStep(evt: EventLike): AgentRunStep | null {
138	  const s = (k: string): string => String(evt[k] ?? '')
139	  switch (evt.type) {
140	    case 'observe': return { icon: '🔍', text: `관찰 · 스텝 ${s('step')} · 요소 ${s('elements')}개`, tone: 'muted' }
141	    case 'thought': return evt.thought ? { icon: '💭', text: s('thought') } : null
142	    case 'action': return { icon: '⚙️', text: s('label') }
143	    case 'result': return { icon: evt.ok ? '✔️' : '✖️', text: s('detail'), tone: evt.ok ? 'ok' : 'warn' }
144	    case 'confirm': return { icon: '⏸️', text: `확인 필요: ${s('label')}`, tone: 'warn' }
145	    case 'ask': return { icon: '❓', text: s('message') }
146	    // 사용자 답변은 디스크(ai-agent-runs.json)에 영구 저장된다 → 비밀번호·카드번호가 평문으로 남지 않게 가린다.
147	    case 'answer': return { icon: '🗣️', text: `답변: ${maskSecrets(s('text'))}`, tone: 'muted' }
148	    case 'report': return { icon: '📄', text: `보고서: ${s('title')} (노트 ${s('notes')}개)`, tone: 'ok' }
149	    case 'done': return { icon: '🏁', text: s('message') || '완료', tone: 'ok' }
150	    case 'error': return { icon: '❌', text: s('message') || '오류', tone: 'warn' }
151	    case 'cancelled': return { icon: '⏹️', text: '중단됨', tone: 'muted' }
152	    default: return null
153	  }
154	}
155	
156	export function recordAgentEvent(runId: string, task: string, evt: EventLike): void {
157	  const list = all()
158	  let run = list.find((r) => r.id === runId)
159	
160	  if (evt.type === 'start') {
161	    if (run) return
162	    run = { id: runId, task: task || String(evt.task ?? '작업'), startedAt: Date.now(), status: 'running', steps: [] }
163	    list.unshift(run)
164	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
165	    schedulePersist(); emitChanged()
166	    return
167	  }
168	
169	  if (!run) {
170	    run = { id: runId, task: task || '작업', startedAt: Date.now(), status: 'running', steps: [] }
171	    list.unshift(run)
172	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
173	  }
174	
175	  if (evt.type === 'usage') {
176	    const n = (k: string): number => (typeof evt[k] === 'number' ? (evt[k] as number) : 0)
177	    const u = run.usage ?? { input: 0, cacheRead: 0, cacheCreate: 0, output: 0, llmCalls: 0 }
178	    u.input += n('input'); u.cacheRead += n('cacheRead'); u.cacheCreate += n('cacheCreate'); u.output += n('output'); u.llmCalls++
179	    run.usage = u
180	    schedulePersist()
181	    return
182	  }
183	
184	  const step = deriveStep(evt)
185	  if (step) {
186	    run.steps.push(step)
187	    // 상한 초과 시 최신(종료 마커 포함) 을 남기도록 오래된 단계를 버린다.
188	    if (run.steps.length > MAX_STEPS_PER_RUN) run.steps.splice(0, run.steps.length - MAX_STEPS_PER_RUN)
189	  }
190	
191	  let transitioned = false
192	  if (evt.type === 'done') { run.status = 'done'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
193	  else if (evt.type === 'error') { run.status = 'error'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
194	  else if (evt.type === 'cancelled') { run.status = 'cancelled'; run.endedAt = Date.now(); transitioned = true }
195	
196	  schedulePersist()
197	  if (transitioned) emitChanged() // 단계마다가 아니라 상태 전환 시에만 목록 갱신(라이브 트레이스는 별도 스트림)
198	}
199	
200	export function deleteAgentRun(id: string): void {
201	  const list = all()
202	  const idx = list.findIndex((r) => r.id === id)
203	  if (idx < 0) return
204	  list.splice(idx, 1)
205	  schedulePersist(); emitChanged()
206	}
207	
208	export function clearAgentRuns(): void {
209	  cache = []
210	  schedulePersist(); emitChanged()
211	}
