      convs: await window.browserAPI.ai.convList(),
      runs: await window.browserAPI.ai.runList(),
    }))()`, true) ?? '{}')

    check('PS1', '대화가 강제 종료 후에도 남는다',
      (after.convs?.length ?? 0) >= 3 && after.convs.some((c) => String(c.title ?? '').includes('질문')),
