    const runA = (after.runs ?? []).find((r) => String(r.task).includes('작업 A'))
    check('PS2', '에이전트 실행 이력이 남고 단계도 보존된다',
      !!runA && (runA.steps ?? 0) > 0 || (after.runs?.length ?? 0) >= 2,
      `이력 ${after.runs?.length ?? 0}건 · A 작업=${!!runA} · 단계 ${runA?.steps ?? 0}개`)

