// ---- X11: chrome.scripting.executeScript (프로그래밍 주입) ----
// MV3 확장은 선언형 content_scripts 말고 이 API 로도 코드를 넣는다(사용자 클릭 시 주입 등).
// 라이브러리(electron-chrome-extensions 4.9.0)에는 scripting 구현이 없다 — Electron 이 주는지
// **직접 불러서** 확인한다. 안 되면 GAP 으로 남겨 매 실행 보이게 한다.
{
  const swTarget = (await getTargetList(args.port)).find((t) => String(t.url).endsWith('/sw.js'))
  let outcome = 'SW 타깃 없음'
  let scripted = null
  if (swTarget) {
    const sw = await connectSession(swTarget, 'sw-scripting')
    await ensureSessionReady(sw)
    outcome = await evalIn(sw, `(async () => {
      try {
        if (!chrome.scripting || typeof chrome.scripting.executeScript !== 'function') return 'API 없음'
        const tabs = await chrome.tabs.query({})
        const t = tabs.find((x) => String(x.url || '').indexOf('127.0.0.1') >= 0)
        if (!t) return '대상 탭 없음(탭 ' + tabs.length + '개)'
        await chrome.scripting.executeScript({ target: { tabId: t.id }, files: ['injected.js'] })
        return 'ok'
      } catch (e) { return '오류: ' + String((e && e.message) || e) }
    })()`, true)
    try { sw.close() } catch { /* ignore */ }
    await sleep(800)
    scripted = p1 ? await evalIn(p1, 'document.documentElement.getAttribute("data-ext-scripted")') : null
  }
  gap('X11', 'chrome.scripting.executeScript 로 넣은 코드가 실제로 실행된다',
    outcome === 'ok' && scripted === 'yes',
    `executeScript 결과=${outcome} · 페이지 표식=${scripted ?? '(없음)'}`,
    'electron-chrome-extensions 4.9.0 에 scripting 구현이 없고(문자열 검색 0건) Electron 35 도'
    + ' 확장용 scripting 을 주지 않는다. 이 API 에 의존하는 MV3 확장은 그 부분이 동작하지 않는다.'
    + ' 구현하면 gap() → check() 로 승격할 것.')
}

// X8·X9·X11 까지 쓰고 나서 닫는다(앞에서 닫으면 그 뒤 검사가 세션을 잃는다).
try { p1?.close() } catch { /* ignore */ }

